import{_ as n,C as o,c as l,o as r,aa as s,G as a}from"./chunks/framework.Cn7WEiMX.js";const b=JSON.parse('{"title":"模型定义文件","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/mod-support/model-definition-files.md","filePath":"wiki/Dynmap/mod-support/model-definition-files.md"}'),d={name:"wiki/Dynmap/mod-support/model-definition-files.md"};function c(p,e,m,_,f,h){const i=o("NolebaseGitContributors"),t=o("NolebaseGitChangelog");return r(),l("div",null,[e[0]||(e[0]=s('<p>Model Definition Files</p> <h1 id="模型定义文件" tabindex="-1">模型定义文件 <a class="header-anchor" href="#模型定义文件" aria-label="Permalink to &quot;模型定义文件&quot;">​</a></h1> <p>模组的模型定义文件为自定义方块提供了物理性质，一般为简单的实心方块。因此，如果某个模组只包含简单的方块，那么就不需要模型定义文件。</p> <p>任何情况下，模型定义文件中定义的模型都有一系列表面或补丁，决定了纹理定义文件中的纹理渲染方式。因为纹理定义独立于模型定义，形状通用的方块模型可重复利用（例如，一个台阶方块的模型可以被其他台阶方块利用，只是应用的纹理有所不同）。</p> <p>定义模型有许多方法，从简到繁（至多可以到由 Java 附属类实现的自定义渲染代码）。不过，越简单的方法通常越高效。</p> <h2 id="纹理定义文件通用内容" tabindex="-1">纹理定义文件通用内容 <a class="header-anchor" href="#纹理定义文件通用内容" aria-label="Permalink to &quot;纹理定义文件通用内容&quot;">​</a></h2> <p>总体上讲，<code>modname:</code>、<code>version:</code>、<code>cfgfile:</code> 及 <code>var:</code> 和其他模块配置相关的配置需要在模型与纹理配置文件中一一对应。可见“纹理与模型定义文件通用功能”部分了解这些配置的详细信息。配置不完整可能会导致渲染问题（应用纹理缺少对应模型）或载入错误（所用模型没有必要的纹理）。</p> <h2 id="定义模型" tabindex="-1">定义模型 <a class="header-anchor" href="#定义模型" aria-label="Permalink to &quot;定义模型&quot;">​</a></h2> <ul><li>定义简单立方体模型 - 至少有一轴小于普通方块的长方体模型 - 见“定义立体模型”。</li> <li>使用现有的自定义模型渲染器 - 台阶、栅栏/墙、玻璃板/铁栅栏 - 见“使用自定义方块渲染器”。</li> <li>定义体积方块模型 - 小方格构成的立体网格 - 见“体积方块模型”。</li> <li>定义补丁模型 - 一组可应用任意纹理的表面 - 见“定义补丁模型”。</li> <li>新建自定义模型渲染器类 - 见编写自定义方块渲染器。</li></ul> ',18)),a(i),a(t)])}const k=n(d,[["render",c]]);export{b as __pageData,k as default};
